param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

function Span-Bridge([bool]$Write){
 $roDef=[type]'System.ReadOnlySpan`1';$spanDef=[type]'System.Span`1';$ro=$roDef.MakeGenericType([type[]]@([char]));$span=$spanDef.MakeGenericType([type[]]@([byte]));[type[]]$signature=@([Text.Encoding],[char[]],[int],[int]);[type[]]$native=@($ro)
 if($Write){$signature+=[type[]]@([byte[]],[int],[int]);$native+=[type[]]@($span)};$method=[Text.Encoding].GetMethod($(if($Write){'GetBytes'}else{'GetByteCount'}),$native);$dm=[Reflection.Emit.DynamicMethod]::new('UnicodeTerminalSpan'+$Write,[int],$signature);$il=$dm.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$ro.GetConstructor([type[]]@([char[]],[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@([byte[]],[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$func=[type]('System.Func`'+($signature.Length+1));return $dm.CreateDelegate($func.MakeGenericType([type[]]@($signature+[int])))
}
function Span-Call($Bridge,[object[]]$Arguments){try{return [ordered]@{ok=$true;count=$Bridge.DynamicInvoke($Arguments)}}catch{return Failure-Of $_}}
$countBridge=Span-Bridge $false;$writeBridge=Span-Bridge $true
$replacements=@(@(),@(0),@(65,0),@(0,66),@(65,0,66),@(55296,56320),@(65,0,55296,56320),@(55296,56320,0,65),@(0,55296,56320,0));$profiles=[Collections.Generic.List[object]]::new();$inputs=@(@(),@(65),@(55296),@(56320),@(55296,56320),@(65,55296),@(65,56320),@(65,55296,56320))
foreach($big in @($false,$true)){foreach($replacement in $replacements){
 $owner=[Text.Encoding]([Text.UnicodeEncoding]::new($big,$true,$false)).Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$replacement));$rows=[Collections.Generic.List[object]]::new()
 foreach($units in $inputs){$source=[char[]](@(56320)+$units+@(55296));$views=@(@(1,$units.Length),@(($units.Length+1),0));if($units.Length){$views+=,@($units.Length,1)};$seen=[Collections.Generic.HashSet[string]]::new();foreach($view in $views){$start=[int]$view[0];$count=[int]$view[1];if(-not $seen.Add("$start,$count")){continue};foreach($before in @($false,$true)){foreach($capacity in @(0,1,2,4,8)){foreach($offset in @(0,2)){
  $countResult=$null;if($before){$argsValue=[object[]]@($owner,$source,$start,$count);$countResult=Span-Call $countBridge $argsValue};$dest=[byte[]](@(99)*($offset+$capacity+3));$argsValue=[object[]]@($owner,$source,$start,$count,$dest,$offset,$capacity);$writeResult=Span-Call $writeBridge $argsValue
  $rows.Add([ordered]@{source=[int[]]$source;start=$start;count=$count;countBefore=$before;capacity=$capacity;offset=$offset;countResult=$countResult;writeResult=$writeResult;after=[int[]]$dest})
 }}}}};$profiles.Add([ordered]@{bigEndian=$big;replacement=[int[]]$replacement;rows=$rows.ToArray()})
}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();profiles=$profiles.ToArray();qualification='NATIVE_STATELESS_UTF16_ENCODER_TERMINAL_REPLACEMENT_HEAP_SPANS_ONLY; NO_JAVA_QUALIFICATION_OR_TASK_ACCEPTANCE'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 19 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF16 terminal encoder replacement span capture: $($profiles.Count) configurations"
